CREATE OR REPLACE FUNCTION public.complete_import(p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.import_batches%rowtype; s_count integer; a_count integer; n_conflicts integer;
begin
 select * into b from public.import_batches where id=p_batch for update;
 if found then perform pg_advisory_xact_lock(hashtext('sac-dia:'||b.operational_day::text)); end if;
 if not found then raise exception 'Importação inexistente'; end if;
 if b.imported_by is distinct from auth.uid() or not private.is_supervisor_of(b.team_id) then raise exception 'Acesso negado';end if;
 if b.state<>'uploading' then raise exception 'Importação não está aberta'; end if;
 if exists(select 1 from public.import_batches recent where recent.team_id=b.team_id and recent.state='ready' and recent.created_at > b.created_at) then
   raise exception 'Uma rodada mais recente já está validada; revise a ordem das importações';
 end if;
 if not private.can_import_shift(b.team_id,b.operational_day,b.shift_label) then raise exception 'Turno/dia já encerrado';end if;
 select count(*) filter(where source='SAC'),count(*) filter(where source='ATIVO') into s_count,a_count from public.import_files where batch_id=p_batch;
 if s_count<>1 or a_count<>1 then raise exception 'São necessárias as bases SAC e ATIVO';end if;
 if exists(select 1 from public.import_files f where f.batch_id=p_batch and f.total_rows<1) then raise exception 'Arquivo sem protocolos';end if;
 if exists(select 1 from public.import_files f where f.batch_id=p_batch and f.total_rows<>(select count(*) from public.import_rows r where r.file_id=f.id)) then raise exception 'Contagem de linhas divergente';end if;
 -- Divergência do mesmo protocolo em um lote é sinalizada. Dados conflitantes não são aplicados à carteira.
 -- Proteção no banco: detectar conflitos adicionais que escaparam ao cliente.
 -- Uma divergência é avaliada por protocolo, sem interromper os demais.
 insert into public.import_conflicts(batch_id,protocol_number,conflict_type,details)
 select p_batch,protocol_number,'database_divergence',jsonb_build_object('reason','Valores divergentes no mesmo lote')
 from (select r.protocol_number
       from public.import_rows r join public.import_files f on f.id=r.file_id
       where f.batch_id=p_batch group by r.protocol_number
       having count(distinct nullif(btrim(r.status_code),''))>1
           or count(distinct nullif(btrim(r.operator_name),''))>1
           or count(distinct nullif(btrim(r.criticality),''))>1) conflicts
 on conflict(batch_id,protocol_number,conflict_type) do nothing;
 select count(distinct protocol_number) into n_conflicts
 from public.import_conflicts where batch_id=p_batch and review_status='pending';
 -- Se houver divergências, a carteira recebe apenas protocolos não ambíguos.
 -- Finalizações por desaparecimento ficam suspensas para evitar falso encerramento.
 -- Guardar apenas os campos essenciais na carteira atual.
 -- Um protocolo com CD_STATUS=12 que desaparece de ambas as fontes é finalizado;
 -- desaparecimento de outros status NÃO gera finalização.
 insert into public.protocol_events(team_id,protocol_number,batch_id,event_type,old_status,new_status)
 select b.team_id,p.protocol_number,p_batch,'finalized',p.last_status_code,null
 from public.protocol_current p
 where n_conflicts=0 and p.team_id=b.team_id and p.lifecycle='active' and p.last_status_code='12'
 and not exists(
    select 1 from public.import_rows r join public.import_files f on f.id=r.file_id
    where f.batch_id=p_batch and r.protocol_number=p.protocol_number
 );
 update public.protocol_current p set lifecycle='finalized',finalized_at=now()
 where n_conflicts=0 and p.team_id=b.team_id and p.lifecycle='active' and p.last_status_code='12'
 and not exists(select 1 from public.import_rows r join public.import_files f on f.id=r.file_id
  where f.batch_id=p_batch and r.protocol_number=p.protocol_number);
 insert into public.protocol_events(team_id,protocol_number,batch_id,event_type,old_status,new_status)
 select b.team_id,r.protocol_number,p_batch,
  case when p.protocol_number is null then 'new'
       when p.lifecycle='finalized' then 'reappeared' else 'changed' end,
  p.last_status_code,r.status_code
 from (select distinct on (ir.protocol_number) ir.protocol_number,ir.status_code,ir.operator_name,ir.criticality
   from public.import_rows ir join public.import_files f on f.id=ir.file_id
   where f.batch_id=p_batch
   and not exists(select 1 from public.import_conflicts c where c.batch_id=p_batch and c.protocol_number=ir.protocol_number and c.review_status='pending')
   order by ir.protocol_number,(f.source='SAC') desc,ir.id desc) r
 left join public.protocol_current p on p.team_id=b.team_id and p.protocol_number=r.protocol_number
 where p.protocol_number is null or p.lifecycle='finalized'
 or p.last_status_code is distinct from coalesce(r.status_code,p.last_status_code)
 or p.operator_name is distinct from coalesce(r.operator_name,p.operator_name)
 or p.criticality is distinct from coalesce(r.criticality,p.criticality);
 insert into public.protocol_current(team_id,protocol_number,last_status_code,operator_name,criticality,last_batch_id)
 select b.team_id,ir.protocol_number,ir.status_code,ir.operator_name,ir.criticality,p_batch
 from (select distinct on (r.protocol_number) r.protocol_number,r.status_code,r.operator_name,r.criticality
    from public.import_rows r join public.import_files f on f.id=r.file_id
    where f.batch_id=p_batch
     and not exists(select 1 from public.import_conflicts c where c.batch_id=p_batch and c.protocol_number=r.protocol_number and c.review_status='pending')
     order by r.protocol_number,(f.source='SAC') desc,r.id desc) ir
 on conflict(team_id,protocol_number) do update
 set last_status_code=coalesce(excluded.last_status_code,public.protocol_current.last_status_code), operator_name=coalesce(excluded.operator_name,public.protocol_current.operator_name),
 criticality=coalesce(excluded.criticality,public.protocol_current.criticality), lifecycle='active',finalized_at=null,
 last_seen_at=now(),last_batch_id=p_batch;
 update public.import_batches set state='ready',ready_at=now(), notes=case when n_conflicts>0 then 'Importação parcial segura: '||n_conflicts||' protocolo(s) com divergência pendente; finalizações suspensas' else null end where id=p_batch;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'IMPORT_READY','import_batch',p_batch::text,jsonb_build_object('final_import',b.final_import,'pending_conflicts',n_conflicts,'finalizations_paused',n_conflicts>0));
 return jsonb_build_object('state','ready','conflicts',n_conflicts,'finalizations_paused',n_conflicts>0);
end;$function$
CREATE OR REPLACE FUNCTION private.can_import_shift(p_team uuid, p_day date, p_shift text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select not exists(select 1 from public.daily_closures d where d.operational_day=p_day and d.status<>'reopened')
 and not exists(select 1 from public.shift_closures s where s.team_id=p_team and s.operational_day=p_day
 and s.shift_label=p_shift and s.status='closed');
$function$
CREATE OR REPLACE FUNCTION private.create_operator_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.profiles (id, full_name, role)
  VALUES (
    NEW.id,
    left(coalesce(nullif(btrim(NEW.raw_user_meta_data ->> 'full_name'), ''), 'Usuário'), 120),
    'operator'
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION private.is_manager()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select exists(select 1 from public.profiles where id=(select auth.uid()) and role in ('manager','admin'));
$function$
CREATE OR REPLACE FUNCTION private.can_read_team(p_team uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select private.is_manager() or exists(select 1 from public.team_memberships where user_id=(select auth.uid()) and team_id=p_team);
$function$
CREATE OR REPLACE FUNCTION private.can_write_batch(p_batch uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select exists(select 1 from public.import_batches b where b.id=p_batch and b.imported_by=(select auth.uid())
 and b.state='uploading' and private.is_supervisor_of(b.team_id));
$function$
CREATE OR REPLACE FUNCTION public.close_shift(p_batch uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.import_batches%rowtype; result uuid;
begin
 select * into b from public.import_batches where id=p_batch for update;
 if found then perform pg_advisory_xact_lock(hashtext('sac-dia:'||b.operational_day::text)); end if;
 if not found or b.state<>'ready' or not b.final_import then raise exception 'Última importação não validada';end if;
 if not private.is_supervisor_of(b.team_id) then raise exception 'Acesso negado';end if;
 if exists(select 1 from public.import_batches x where x.team_id=b.team_id and x.operational_day=b.operational_day and x.shift_label=b.shift_label and x.state='ready' and x.created_at>b.created_at) then raise exception 'Há importação posterior; revise a última rodada';end if;
 if exists(select 1 from public.daily_closures where operational_day=b.operational_day and status<>'reopened') then raise exception 'Dia já encerrado';end if;
 insert into public.shift_closures(team_id,operational_day,shift_label,batch_id,closed_by)
 values(b.team_id,b.operational_day,b.shift_label,p_batch,auth.uid()) returning id into result;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'SHIFT_CLOSED','shift_closure',result::text,jsonb_build_object('batch_id',p_batch));
 return result;
exception when unique_violation then raise exception 'Esse turno já foi fechado';
end;$function$
CREATE OR REPLACE FUNCTION public.close_day(p_day date, p_justification text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n_pending integer; result uuid; snap jsonb;
begin
 if not private.is_manager() then raise exception 'Apenas gestor ou administrador';end if;
 perform pg_advisory_xact_lock(hashtext('sac-dia:'||p_day::text));
 -- As equipes com atividade na data integram o fechamento; não presumir 4 turnos.
 select count(*) into n_pending from (
  (select team_id,shift_label from public.shift_expectations where operational_day=p_day
   union select distinct b.team_id,b.shift_label from public.import_batches b where b.operational_day=p_day and b.state='ready')
  except select c.team_id,c.shift_label from public.shift_closures c where c.operational_day=p_day and c.status='closed'
 ) pend;
 if n_pending>0 and length(trim(coalesce(p_justification,'')))<10 then
    raise exception 'Informe justificativa de pelo menos 10 caracteres para fechamento com pendências';
 end if;
 select jsonb_build_object('rounds',count(*),'team_count',count(distinct team_id),'closed_shifts',
  (select count(*) from public.shift_closures where operational_day=p_day and status='closed')) into snap
 from public.import_batches where operational_day=p_day and state='ready';
 if (snap->>'rounds')::integer=0 then raise exception 'Sem importações válidas na data';end if;
 insert into public.daily_closures(operational_day,status,closed_by,pending_team_count,justification,snapshot)
 values(p_day,case when n_pending>0 then 'closed_with_pending' else 'closed' end,auth.uid(),n_pending,p_justification,snap)
 on conflict(operational_day) do update set
  status=excluded.status,closed_by=excluded.closed_by,closed_at=now(),
  pending_team_count=excluded.pending_team_count,justification=excluded.justification,
  snapshot=excluded.snapshot, reopened_at=null,reopened_by=null,reopen_reason=null
 where public.daily_closures.status='reopened'
 returning id into result;
 if result is null then raise exception 'Dia já possui fechamento ativo';end if;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'DAY_CLOSED','daily_closure',result::text,snap||jsonb_build_object('pending',n_pending));
 return result;
exception when unique_violation then raise exception 'Dia já possui fechamento; reabertura exige processo auditado';
end;$function$
CREATE OR REPLACE FUNCTION public.reopen_day(p_day date, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.daily_closures%rowtype;
begin
 if not private.is_manager() then raise exception 'Apenas gestor ou administrador';end if;
 if length(trim(coalesce(p_reason,'')))<10 then raise exception 'Justificativa insuficiente';end if;
 select * into d from public.daily_closures where operational_day=p_day for update;
 if not found or d.status='reopened' then raise exception 'Dia não está fechado';end if;
 update public.daily_closures set status='reopened',reopened_at=now(),reopened_by=auth.uid(),reopen_reason=p_reason where id=d.id;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'DAY_REOPENED','daily_closure',d.id::text,jsonb_build_object('reason',p_reason,'previous',to_jsonb(d)));
end;$function$
CREATE OR REPLACE FUNCTION private.can_read_protocol(p_team uuid, p_protocol text, p_operator text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select (select private.is_manager()) or private.is_supervisor_of(p_team) or exists (
   select 1 from public.profiles p
   where p.id=(select auth.uid()) and p.role='operator'
   and (exists (
     select 1 from public.protocol_assignments a
     where a.team_id=p_team and a.protocol_number=p_protocol and a.operator_user_id=p.id
   ) or (
     not exists(select 1 from public.protocol_assignments a
      where a.team_id=p_team and a.protocol_number=p_protocol)
     and exists(select 1 from public.operator_links l
       where l.team_id=p_team and l.user_id=p.id and lower(trim(l.operator_name))=lower(trim(coalesce(p_operator,'')))
     )
   ))
 );
$function$
CREATE OR REPLACE FUNCTION public.admin_link_operator(p_team uuid, p_user uuid, p_operator_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.is_manager() then raise exception 'Somente gestor ou administrador vincula operadores';end if;
 if not exists(select 1 from public.profiles where id=p_user and role='operator')
 then raise exception 'Selecione uma conta com perfil Operador';end if;
 if length(trim(coalesce(p_operator_name,'')))<2 then raise exception 'Informe o nome operacional';end if;
 insert into public.operator_links(team_id,user_id,operator_name,linked_by)
 values(p_team,p_user,trim(p_operator_name),auth.uid())
 on conflict(team_id,user_id) do update set operator_name=excluded.operator_name,
 linked_by=excluded.linked_by,linked_at=now();
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'OPERATOR_LINKED','operator_link',p_user::text,
 jsonb_build_object('team_id',p_team,'operator_name',p_operator_name));
end;$function$
CREATE OR REPLACE FUNCTION public.assign_protocol(p_team uuid, p_protocol text, p_operator uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not (private.is_manager() or private.is_supervisor_of(p_team)) then raise exception 'Acesso negado';end if;
 if not exists(select 1 from public.operator_links where team_id=p_team and user_id=p_operator)
 then raise exception 'Operador não está vinculado à equipe';end if;
 if not exists(select 1 from public.protocol_current where team_id=p_team and protocol_number=p_protocol)
 then raise exception 'Protocolo não encontrado';end if;
 insert into public.protocol_assignments(team_id,protocol_number,operator_user_id,assigned_by)
 values(p_team,p_protocol,p_operator,auth.uid())
 on conflict(team_id,protocol_number) do update set operator_user_id=excluded.operator_user_id,
 assigned_by=excluded.assigned_by,assigned_at=now();
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'PROTOCOL_ASSIGNED','protocol',p_protocol,
 jsonb_build_object('team_id',p_team,'operator_user_id',p_operator));
end;$function$
CREATE OR REPLACE FUNCTION public.record_operator_treatment(p_team uuid, p_protocol text, p_kind text, p_notes text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_operator text; v_id bigint;
begin
 select operator_name into v_operator from public.protocol_current
 where team_id=p_team and protocol_number=p_protocol;
 if not found or not private.can_read_protocol(p_team,p_protocol,v_operator)
 then raise exception 'Protocolo não autorizado';end if;
 if p_kind not in ('in_progress','awaiting','note','completed_in_tool')
 then raise exception 'Tipo de anotação inválido';end if;
 if length(trim(coalesce(p_notes,'')))<3 then raise exception 'Descreva o atendimento';end if;
 insert into public.operator_treatments(team_id,protocol_number,actor_id,treatment_type,notes)
 values(p_team,p_protocol,auth.uid(),p_kind,trim(p_notes)) returning id into v_id;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'TREATMENT_ADDED','protocol',p_protocol,jsonb_build_object('team_id',p_team,'type',p_kind));
 return v_id;
end;$function$
CREATE OR REPLACE FUNCTION public.shift_import_preview(p_batch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.import_batches%rowtype; r jsonb;
begin
 select * into b from public.import_batches where id=p_batch;
 if not found or not (private.is_manager() or private.is_supervisor_of(b.team_id))
 then raise exception 'Importação não autorizada';end if;
 if b.state<>'ready' or not b.final_import then raise exception 'Última importação ainda não validada';end if;
 select jsonb_build_object(
  'batch',b.id,'day',b.operational_day,'shift',b.shift_label,'team_id',b.team_id,
  'files',(select jsonb_object_agg(source,total_rows) from public.import_files where batch_id=b.id),
  'protocols',(select count(distinct r.protocol_number) from public.import_rows r join public.import_files f on f.id=r.file_id where f.batch_id=b.id),
  'new',(select count(*) from public.protocol_events where batch_id=b.id and event_type='new'),
  'changed',(select count(*) from public.protocol_events where batch_id=b.id and event_type='changed'),
  'finalized',(select count(*) from public.protocol_events where batch_id=b.id and event_type='finalized'),
  'reappeared',(select count(*) from public.protocol_events where batch_id=b.id and event_type='reappeared'),
  'pending',(select count(*) from public.protocol_current where team_id=b.team_id and lifecycle='active'),
  'conflicts',0
 ) into r;
 return r;
end;$function$
CREATE OR REPLACE FUNCTION public.discard_upload(p_batch uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.import_batches%rowtype;
BEGIN
 SELECT * INTO b FROM public.import_batches WHERE id=p_batch FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF b.imported_by IS DISTINCT FROM auth.uid() OR NOT private.is_supervisor_of(b.team_id)
   OR b.state <> 'uploading' THEN RAISE EXCEPTION 'Lote indisponível para cancelamento'; END IF;
 DELETE FROM public.import_batches WHERE id=p_batch;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'UPLOAD_DISCARDED','import_batch',p_batch::text,
 jsonb_build_object('team_id',b.team_id,'day',b.operational_day));
 RETURN true;
END;$function$
CREATE OR REPLACE FUNCTION public.management_summary(p_team uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb;
begin
 if not (private.is_manager() or exists(select 1 from public.team_memberships
   where user_id=auth.uid() and team_id=coalesce(p_team,team_id) and
   exists(select 1 from public.profiles where id=auth.uid() and role='supervisor')))
 then raise exception 'Acesso gerencial necessário';end if;
 if p_team is not null and not (private.is_manager() or private.is_supervisor_of(p_team))
 then raise exception 'Equipe não autorizada';end if;
 with visible as (select p.* from public.protocol_current p
   where (p_team is null or p.team_id=p_team) and
   (private.is_manager() or private.is_supervisor_of(p.team_id)))
 select jsonb_build_object(
   'total',(select count(*) from visible),
   'active',(select count(*) from visible where lifecycle='active'),
   'finalized',(select count(*) from visible where lifecycle='finalized'),
   'by_criticality',(select coalesce(jsonb_agg(jsonb_build_object('name',criticality,'value',n) order by n desc),'[]'::jsonb) from
     (select coalesce(nullif(trim(criticality),''),'Não informada') criticality,count(*) n from visible where lifecycle='active' group by 1) g),
   'by_status',(select coalesce(jsonb_agg(jsonb_build_object('name',last_status_code,'value',n) order by n desc),'[]'::jsonb) from
     (select coalesce(nullif(trim(last_status_code),''),'Não informado') last_status_code,count(*) n from visible where lifecycle='active' group by 1) g),
   'by_team',(select coalesce(jsonb_agg(jsonb_build_object('id',team_id,'value',n) order by n desc),'[]'::jsonb) from
     (select team_id,count(*) n from visible where lifecycle='active' group by 1) g)
 ) into v;
 return v;
end;$function$
CREATE OR REPLACE FUNCTION public.plan_shift(p_team uuid, p_day date, p_shift text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.is_manager() then raise exception 'Somente gestor/administrador planeja o turno';end if;
 if length(trim(coalesce(p_shift,'')))<2 then raise exception 'Turno inválido';end if;
 if exists(select 1 from public.daily_closures where operational_day=p_day and status<>'reopened') then raise exception 'O dia está encerrado';end if;
 insert into public.shift_expectations(team_id,operational_day,shift_label,created_by)
 values(p_team,p_day,p_shift,auth.uid()) on conflict do nothing;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(auth.uid(),'SHIFT_PLANNED','shift_expectation',p_day::text,jsonb_build_object('team_id',p_team,'shift',p_shift));
end;$function$
CREATE OR REPLACE FUNCTION private.purge_expired_history(p_today date DEFAULT ((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n_batches integer; n_shifts integer; n_days integer; n_finalized integer; n_expectations integer;
begin
 create temporary table if not exists purge_days(day date primary key) on commit drop;
 truncate purge_days;
 insert into purge_days(day)
 select operational_day from public.daily_closures d
 where d.operational_day < (p_today - interval '2 months')::date
 and d.status in ('closed','closed_with_pending')
 and not exists(select 1 from public.retention_holds h where h.operational_day=d.operational_day and h.released_at is null);
 delete from public.shift_closures where operational_day in(select day from purge_days);
 get diagnostics n_shifts=row_count;
 delete from public.shift_expectations where operational_day in(select day from purge_days);
 get diagnostics n_expectations=row_count;
 delete from public.import_batches where operational_day in(select day from purge_days);
 get diagnostics n_batches=row_count;
 delete from public.daily_closures where operational_day in(select day from purge_days);
 get diagnostics n_days=row_count;
 -- Limpa apenas protocolos FINALIZADOS antigos, nunca a carteira ativa.
 delete from public.protocol_current p
 where p.lifecycle='finalized' and p.finalized_at < (p_today::timestamp - interval '2 months')
 and not exists(select 1 from public.retention_holds h
  where h.operational_day=(p.finalized_at at time zone 'America/Sao_Paulo')::date and h.released_at is null);
 get diagnostics n_finalized=row_count;
 insert into public.audit_events(user_id,action,object_type,object_id,details)
 values(null,'HISTORY_PURGED','retention',p_today::text,jsonb_build_object('days',n_days,'batches',n_batches,'finalized_protocols',n_finalized));
 return jsonb_build_object('deleted_days',n_days,'deleted_shifts',n_shifts,'deleted_batches',n_batches,'deleted_finalized_protocols',n_finalized,'deleted_expectations',n_expectations);
end;$function$
CREATE OR REPLACE FUNCTION private.is_supervisor_of(p_team uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select private.is_manager() or exists(select 1 from public.profiles p join public.team_memberships m on m.user_id=p.id
 where p.id=(select auth.uid()) and m.team_id=p_team and p.role='supervisor');
$function$
CREATE OR REPLACE FUNCTION public.create_import_team(p_operation uuid, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;
BEGIN
 IF NOT private.is_manager() THEN RAISE EXCEPTION 'Acesso gerencial necessário'; END IF;
 IF length(btrim(coalesce(p_name,''))) < 2 OR length(p_name)>80 THEN RAISE EXCEPTION 'Nome da equipe inválido'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.operations o WHERE o.id=p_operation AND o.active) THEN
   RAISE EXCEPTION 'Operação não encontrada ou inativa'; END IF;
 INSERT INTO public.teams(operation_id,name,active)
 VALUES(p_operation,btrim(p_name),true)
 ON CONFLICT(operation_id,name) DO UPDATE SET active=true
 RETURNING id INTO v_id;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'TEAM_READY','team',v_id::text,jsonb_build_object('name',p_name));
 RETURN v_id;
END;$function$
CREATE OR REPLACE FUNCTION private.audit_daily_distribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.updated_by IS DISTINCT FROM auth.uid() THEN
     RAISE EXCEPTION 'Atualização não autorizada';
  END IF;
  NEW.updated_at := now();
  INSERT INTO public.daily_result_distribution_audit(snapshot_id,changed_by,state_hash,record_count)
  VALUES (NEW.snapshot_id,auth.uid(),md5(NEW.state::text),
    (SELECT COUNT(*) FROM jsonb_object_keys(CASE WHEN jsonb_typeof(NEW.state->'assignments')='object' THEN NEW.state->'assignments' ELSE '{}'::jsonb END)));
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_priority_reason(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 SELECT CASE WHEN p_value IN ('Prazo vencido','Vence hoje','Prazo D6','Histórico de NIP','Fila crítica','Credenciamento D6','Prazo D5/D4','Tempo excedido no retorno','Prazo regular','Prioridade operacional','Sem classificação de prazo') THEN p_value ELSE NULL END;
$function$
CREATE OR REPLACE FUNCTION private.sri_audit_criticality_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NOT NULL AND OLD.criticality IS DISTINCT FROM NEW.criticality THEN
  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES(auth.uid(),'TASK_CRITICALITY_CHANGED','daily_operator_task',NEW.id::text,jsonb_build_object('before',OLD.criticality,'after',NEW.criticality,'reason',NEW.priority_reason));
 END IF;
 RETURN NEW;
END; $function$
CREATE OR REPLACE FUNCTION public.sri_activate_assigned_operator_accounts(p_snapshot uuid, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_team uuid; v_revision bigint; v_state jsonb;
  v_user uuid; v_role text; v_status text;
  v_new_links integer:=0; v_checked integer:=0; v_joined integer;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
  SELECT s.team_id, d.revision, d.state INTO v_team, v_revision, v_state
    FROM public.daily_result_snapshots s
    JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
   WHERE s.id=p_snapshot;
  IF NOT FOUND THEN RAISE EXCEPTION 'Apuração ou distribuição inexistente'; END IF;
  IF NOT (private.is_manager() OR private.is_supervisor_of(v_team)) THEN
    RAISE EXCEPTION 'Somente gestão ou supervisão da equipe pode vincular operadores';
  END IF;
  IF v_revision<>p_revision THEN
    RAISE EXCEPTION 'Distribuição alterada em outra sessão: atualize a apuração';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id=v_team AND active) THEN
    RAISE EXCEPTION 'A equipe de destino está inativa';
  END IF;
  IF jsonb_typeof(v_state->'assignments') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Distribuição inválida';
  END IF;

  FOR v_user IN
    SELECT DISTINCT substring(e.value->>'opId' from 6)::uuid
      FROM jsonb_each(v_state->'assignments') e
     WHERE e.value->>'opId' ~ '^acct:[0-9a-fA-F-]{36}$'
     ORDER BY 1
  LOOP
    SELECT p.role,p.operational_status INTO v_role,v_status
      FROM public.profiles p WHERE p.id=v_user FOR UPDATE;
    IF NOT FOUND OR v_role<>'operator' OR v_status NOT IN ('Ativo','Promovido') THEN
      RAISE EXCEPTION 'A distribuição contém um perfil inexistente ou operador indisponível';
    END IF;
    IF EXISTS(SELECT 1 FROM public.team_memberships tm WHERE tm.user_id=v_user AND tm.team_id<>v_team)
      OR EXISTS(SELECT 1 FROM public.daily_operator_tasks t WHERE t.operator_user_id=v_user AND t.team_id IS DISTINCT FROM v_team AND t.active AND private.sri_task_blocks_transfer(t.operational_day,t.team_id,t.shift_label)) THEN
      RAISE EXCEPTION 'Operador já pertence a outra equipe; solicite à gestão a transferência autorizada';
    END IF;

    INSERT INTO public.team_memberships(user_id,team_id)
      VALUES(v_user,v_team) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_joined=ROW_COUNT;
    INSERT INTO public.operator_links(team_id,user_id,operator_name,linked_by)
      VALUES(v_team,v_user,'USER:'||v_user::text,(SELECT auth.uid()))
      ON CONFLICT (team_id,user_id) DO NOTHING;

    IF v_joined>0 THEN
      v_new_links:=v_new_links+1;
      INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
        VALUES((SELECT auth.uid()),'DISTRIBUTION_OPERATOR_AUTO_LINKED','profile',v_user::text,
          jsonb_build_object('team_id',v_team,'snapshot_id',p_snapshot,'revision',p_revision));
    END IF;
    v_checked:=v_checked+1;
  END LOOP;
  RETURN jsonb_build_object('checked',v_checked,'auto_linked',v_new_links);
END;
$function$
CREATE OR REPLACE FUNCTION public.publish_daily_operator_tasks(p_snapshot uuid, p_revision bigint, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_team uuid; v_day date; v_shift text; v_state jsonb; v_revision bigint;
  v_assignments jsonb; v_roster jsonb; v_archive jsonb;
  v_id text; v_opid text; v_name text; v_user uuid;
  v_entry record; v_detail jsonb; v_criticality text; v_latest uuid; v_lock_day date;
  v_published integer:=0; v_unlinked integer:=0; v_changed integer:=0;
  v_unlinked_names jsonb:='[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão obrigatória'; END IF;
  SELECT operational_day INTO v_lock_day FROM public.daily_result_snapshots WHERE id=p_snapshot;
  IF NOT FOUND THEN RAISE EXCEPTION 'Apuração ou distribuição inexistente'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_lock_day::text,0));
  IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' THEN
    RAISE EXCEPTION 'Detalhes inválidos';
  END IF;
  SELECT s.team_id,s.operational_day,s.shift_label,d.state,d.revision
  INTO v_team,v_day,v_shift,v_state,v_revision
  FROM public.daily_result_snapshots s
  JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
  WHERE s.id=p_snapshot FOR SHARE OF d;
  IF NOT FOUND THEN RAISE EXCEPTION 'Apuração ou distribuição inexistente'; END IF;
  IF NOT (private.is_manager() OR private.is_supervisor_of(v_team)) THEN
    RAISE EXCEPTION 'Somente gestão/supervisão da equipe pode publicar'; END IF;
  IF v_revision<>p_revision THEN
    RAISE EXCEPTION 'A distribuição mudou em outro navegador. Recarregue antes de publicar'; END IF;
  -- Não permita que apurações históricas desativem tarefas da apuração mais recente.
  SELECT s.id INTO v_latest FROM public.daily_result_snapshots s
  WHERE s.team_id=v_team AND s.operational_day=v_day AND s.shift_label=v_shift
  ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
  IF v_latest IS DISTINCT FROM p_snapshot THEN
    RAISE EXCEPTION 'Apuração anterior: recupere a rodada mais recente antes de publicar carteiras';
  END IF;
  IF EXISTS(SELECT 1 FROM public.sri_result_shift_closures c WHERE c.team_id=v_team AND c.operational_day=v_day AND c.shift_label=v_shift AND c.status='closed')
     OR EXISTS(SELECT 1 FROM public.sri_result_day_closures d WHERE d.operational_day=v_day AND d.status IN ('closed','closed_with_pending')) THEN
    RAISE EXCEPTION 'Turno ou dia encerrado: solicite reabertura autorizada antes de publicar';
  END IF;
  v_assignments:=COALESCE(v_state->'assignments','{}'::jsonb);
  v_roster:=COALESCE(v_state->'roster','[]'::jsonb);
  v_archive:=COALESCE(v_state->'archivedRoster','[]'::jsonb);
  IF jsonb_typeof(v_assignments)<>'object' OR jsonb_typeof(v_roster)<>'array'
     OR jsonb_typeof(v_archive)<>'array' THEN
    RAISE EXCEPTION 'Estrutura da distribuição incompatível';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(v_assignments))>15000 THEN
    RAISE EXCEPTION 'Distribuição excede 15 mil atribuições por rodada';
  END IF;
  FOR v_entry IN SELECT key,value FROM jsonb_each(v_assignments) LOOP
    v_id:=btrim(v_entry.key);
    v_opid:=v_entry.value->>'opId';
    IF v_id IS NULL OR length(v_id)<1 OR length(v_id)>100 OR v_opid IS NULL THEN CONTINUE; END IF;
    SELECT item->>'name' INTO v_name FROM (
      SELECT item FROM jsonb_array_elements(v_roster) AS z(item)
      UNION ALL
      SELECT item FROM jsonb_array_elements(v_archive) AS z(item)
    ) list WHERE list.item->>'id'=v_opid LIMIT 1;
    v_user:=NULL;
    -- Para novos cadastros o ID da conta é o identificador da distribuição.
    -- A equipe e a situação são confirmadas NO BANCO, sem confiar no navegador.
    IF v_opid ~ '^acct:[0-9a-fA-F-]{36}$' THEN
      SELECT p.id INTO v_user FROM public.profiles p
      JOIN public.team_memberships tm ON tm.user_id=p.id AND tm.team_id=v_team
      JOIN public.operator_links link ON link.user_id=p.id AND link.team_id=v_team
      WHERE p.id=substring(v_opid from 6)::uuid AND p.role='operator'
        AND p.operational_status IN ('Ativo','Promovido')
      LIMIT 1;
    ELSIF v_name IS NOT NULL THEN
      -- Compatibilidade de históricos: somente vínculos já conferidos manualmente.
      SELECT link.user_id INTO v_user FROM public.operator_links link
      JOIN public.profiles p ON p.id=link.user_id AND p.role='operator'
      JOIN public.team_memberships tm ON tm.user_id=link.user_id AND tm.team_id=link.team_id
      WHERE link.team_id=v_team AND p.operational_status IN ('Ativo','Promovido')
        AND lower(btrim(link.operator_name))=lower(btrim(v_name))
      LIMIT 1;
    END IF;
    IF v_user IS NULL THEN
      v_unlinked:=v_unlinked+1;
      IF jsonb_array_length(v_unlinked_names)<15 THEN
         v_unlinked_names:=v_unlinked_names || jsonb_build_array(COALESCE(v_name,'Operador não identificado'));
      END IF;
      CONTINUE;
    END IF;
    v_detail:=COALESCE(p_details->v_id,'{}'::jsonb);
    IF jsonb_typeof(v_detail)<>'object' THEN v_detail:='{}'::jsonb; END IF;
    v_criticality:=COALESCE(NULLIF(v_state->'criticities'->v_id->>'value',''),NULLIF(v_detail->>'criticality',''));
    INSERT INTO public.daily_operator_tasks
    (snapshot_id,team_id,operational_day,shift_label,protocol_number,operator_user_id,
     criticality,due_situation,sla_band,channel,source_status,distribution_revision,active,priority_reason,due_date,base_name,area_name)
    VALUES
    (p_snapshot,v_team,v_day,v_shift,v_id,v_user,
     left(v_criticality,80),left(v_detail->>'situation',80),left(v_detail->>'sla',50),
     left(v_detail->>'channel',80),left(v_detail->>'status',80),
     v_revision,true,private.sri_priority_reason(v_detail->>'priority_reason'),private.sri_priority_date(v_detail->>'due_date'),left(v_detail->>'base',120),left(v_detail->>'area',120))
    ON CONFLICT(snapshot_id,protocol_number) DO UPDATE SET
      operator_user_id=EXCLUDED.operator_user_id,
      criticality=EXCLUDED.criticality,priority_reason=EXCLUDED.priority_reason,due_date=EXCLUDED.due_date,
      due_situation=EXCLUDED.due_situation,
      sla_band=EXCLUDED.sla_band,
      channel=EXCLUDED.channel,
      source_status=COALESCE(EXCLUDED.source_status,daily_operator_tasks.source_status),base_name=COALESCE(EXCLUDED.base_name,daily_operator_tasks.base_name),area_name=COALESCE(EXCLUDED.area_name,daily_operator_tasks.area_name),
      active=true,distribution_revision=EXCLUDED.distribution_revision,updated_at=now(),
      work_status=public.daily_operator_tasks.work_status;
    v_published:=v_published+1;
  END LOOP;
  -- Desativa atribuições removidas, sem excluir histórico. Também invalida rodadas anteriores do mesmo turno.
  UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
  WHERE t.snapshot_id=p_snapshot AND t.active AND t.distribution_revision<>v_revision;
  GET DIAGNOSTICS v_changed=ROW_COUNT;
  UPDATE public.daily_operator_tasks t SET active=false,updated_at=now()
  WHERE t.snapshot_id<>p_snapshot AND t.team_id=v_team AND t.operational_day=v_day
    AND t.shift_label=v_shift AND t.active;
  INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
  VALUES(auth.uid(),'DAY_OPERATOR_TASKS_PUBLISHED','daily_result',p_snapshot::text,
         jsonb_build_object('revision',v_revision,'published',v_published,'unlinked',v_unlinked,'deactivated',v_changed));
  RETURN jsonb_build_object('published',v_published,'unlinked',v_unlinked,
                            'unlinked_names',v_unlinked_names,'revision',v_revision);
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_manage_catalog_impl(p_kind text, p_action text, p_id uuid, p_name text, p_operation uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_before jsonb; v_after jsonb; v_op uuid; v_fk record; v_ref boolean;
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN RAISE EXCEPTION 'Ação exclusiva da gestão'; END IF;
 IF p_kind NOT IN ('teams','operations') OR p_kind IS NULL OR p_action NOT IN ('create','edit','enable','disable','delete') OR p_action IS NULL THEN RAISE EXCEPTION 'Ação inválida'; END IF;
 IF p_action IN ('create','edit') AND (length(btrim(coalesce(p_name,'')))<2 OR length(btrim(p_name))>80) THEN RAISE EXCEPTION 'Informe um nome entre 2 e 80 caracteres'; END IF;
 IF p_kind='teams' AND p_action IN ('create','edit','enable') THEN
   IF p_action='enable' THEN SELECT operation_id INTO v_op FROM public.teams WHERE id=p_id; ELSE v_op:=p_operation; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.operations WHERE id=v_op AND active FOR SHARE) THEN RAISE EXCEPTION 'Selecione uma operação ativa'; END IF;
 END IF;
 IF p_action='create' THEN
   IF p_kind='teams' THEN INSERT INTO public.teams(operation_id,name,active) VALUES(v_op,btrim(p_name),true) RETURNING id,to_jsonb(teams) INTO v_id,v_after;
   ELSE INSERT INTO public.operations(name,active) VALUES(btrim(p_name),true) RETURNING id,to_jsonb(operations) INTO v_id,v_after; END IF;
 ELSE
   IF p_kind='teams' THEN SELECT to_jsonb(t) INTO v_before FROM public.teams t WHERE id=p_id FOR UPDATE;
   ELSE SELECT to_jsonb(o) INTO v_before FROM public.operations o WHERE id=p_id FOR UPDATE; END IF;
   IF v_before IS NULL THEN RAISE EXCEPTION 'Cadastro não encontrado'; END IF;
   v_id:=p_id;
   IF p_kind='teams' AND (p_action IN ('disable','delete') OR (p_action='edit' AND v_op IS DISTINCT FROM (v_before->>'operation_id')::uuid)) THEN
     IF EXISTS(SELECT 1 FROM public.team_memberships WHERE team_id=p_id) THEN RAISE EXCEPTION 'Transfira os integrantes antes de continuar'; END IF;
     IF EXISTS(SELECT 1 FROM public.daily_operator_tasks WHERE team_id=p_id AND active) THEN RAISE EXCEPTION 'Redistribua os protocolos ativos antes de continuar'; END IF;
   END IF;
   IF p_kind='operations' AND p_action='disable' AND EXISTS(SELECT 1 FROM public.teams WHERE operation_id=p_id AND active) THEN RAISE EXCEPTION 'Inative as equipes vinculadas antes de continuar'; END IF;
   -- Qualquer referência, inclusive vínculos com ON DELETE CASCADE, impede exclusão.
   IF p_action='delete' OR (p_kind='teams' AND p_action='edit' AND v_op IS DISTINCT FROM (v_before->>'operation_id')::uuid) THEN
     FOR v_fk IN SELECT ns.nspname AS schema_name, cl.relname AS table_name, att.attname AS column_name
       FROM pg_constraint co JOIN pg_class cl ON cl.oid=co.conrelid JOIN pg_namespace ns ON ns.oid=cl.relnamespace
       JOIN pg_attribute att ON att.attrelid=co.conrelid AND att.attnum=co.conkey[1]
       WHERE co.contype='f' AND co.confrelid=CASE WHEN p_kind='teams' THEN 'public.teams'::regclass ELSE 'public.operations'::regclass END
       AND cardinality(co.conkey)=1
     LOOP
       EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I WHERE %I=$1)',v_fk.schema_name,v_fk.table_name,v_fk.column_name) INTO v_ref USING p_id;
       IF v_ref THEN RAISE EXCEPTION 'Há vínculos ou registros históricos. Preserve o cadastro e utilize a inativação quando possível'; END IF;
     END LOOP;
   END IF;
   IF p_kind='teams' THEN
     CASE p_action
       WHEN 'edit' THEN UPDATE public.teams SET name=btrim(p_name),operation_id=v_op WHERE id=p_id RETURNING to_jsonb(teams) INTO v_after;
       WHEN 'enable' THEN UPDATE public.teams SET active=true WHERE id=p_id RETURNING to_jsonb(teams) INTO v_after;
       WHEN 'disable' THEN UPDATE public.teams SET active=false WHERE id=p_id RETURNING to_jsonb(teams) INTO v_after;
       WHEN 'delete' THEN DELETE FROM public.teams WHERE id=p_id;
     END CASE;
   ELSE
     CASE p_action
       WHEN 'edit' THEN UPDATE public.operations SET name=btrim(p_name) WHERE id=p_id RETURNING to_jsonb(operations) INTO v_after;
       WHEN 'enable' THEN UPDATE public.operations SET active=true WHERE id=p_id RETURNING to_jsonb(operations) INTO v_after;
       WHEN 'disable' THEN UPDATE public.operations SET active=false WHERE id=p_id RETURNING to_jsonb(operations) INTO v_after;
       WHEN 'delete' THEN DELETE FROM public.operations WHERE id=p_id;
     END CASE;
   END IF;
 END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details) VALUES(auth.uid(),'CATALOG_'||upper(p_action),p_kind,v_id::text,jsonb_build_object('before',v_before,'after',v_after));
 RETURN v_id;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'Já existe um cadastro com esse nome. Consulte também os inativos';
WHEN foreign_key_violation THEN RAISE EXCEPTION 'Existem vínculos ou histórico. Não foi possível concluir';
END; $function$
CREATE OR REPLACE FUNCTION private.sri_task_blocks_transfer(p_day date, p_team uuid, p_shift text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 SELECT p_day >= (now() AT TIME ZONE 'America/Fortaleza')::date OR NOT (
  EXISTS(SELECT 1 FROM public.sri_general_day_closures g WHERE g.operational_day=p_day AND g.status IN ('closed','closed_with_pending'))
  OR EXISTS(SELECT 1 FROM public.sri_result_day_closures d WHERE d.operational_day=p_day AND d.status IN ('closed','closed_with_pending'))
  OR EXISTS(SELECT 1 FROM public.sri_result_shift_closures s WHERE s.operational_day=p_day AND s.team_id=p_team AND s.shift_label=p_shift AND s.status='closed')
 );
$function$
CREATE OR REPLACE FUNCTION private.sri_priority_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
BEGIN
 IF p_value IS NULL OR p_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN NULL; END IF;
 RETURN p_value::date;
EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN NULL;
END; $function$
CREATE OR REPLACE FUNCTION private.sri_sync_profile_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.profiles(id,full_name,role,contact_email)
  VALUES(NEW.id,left(coalesce(nullif(btrim(NEW.raw_user_meta_data->>'full_name'),''),'Usuário'),120),'operator',lower(NEW.email))
  ON CONFLICT (id) DO UPDATE SET contact_email=EXCLUDED.contact_email;
  RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_protect_closed_tasks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS (SELECT 1 FROM public.sri_result_shift_closures c
    WHERE c.team_id=NEW.team_id AND c.operational_day=NEW.operational_day
      AND c.shift_label=NEW.shift_label AND c.status='closed')
    OR EXISTS(SELECT 1 FROM public.sri_result_day_closures d
    WHERE d.operational_day=NEW.operational_day AND d.status IN ('closed','closed_with_pending'))
 THEN
  IF TG_OP='INSERT' THEN RAISE EXCEPTION 'Turno ou dia fechado: não é possível publicar novas atribuições'; END IF;
  IF OLD.operator_user_id IS DISTINCT FROM NEW.operator_user_id
    OR OLD.distribution_revision IS DISTINCT FROM NEW.distribution_revision
    OR OLD.active IS DISTINCT FROM NEW.active
    OR OLD.criticality IS DISTINCT FROM NEW.criticality
    OR OLD.due_situation IS DISTINCT FROM NEW.due_situation
    OR OLD.sla_band IS DISTINCT FROM NEW.sla_band
    OR OLD.channel IS DISTINCT FROM NEW.channel
    OR OLD.source_status IS DISTINCT FROM NEW.source_status
  THEN RAISE EXCEPTION 'Turno ou dia fechado: reabertura necessária antes de redistribuir'; END IF;
 END IF;
 RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_plan_result_shift(p_team uuid, p_day date, p_shift text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN
   RAISE EXCEPTION 'Somente Gestor/Administrador pode planejar turnos'; END IF;
 IF p_team IS NULL OR NOT EXISTS(SELECT 1 FROM public.teams WHERE id=p_team AND active) THEN
   RAISE EXCEPTION 'Equipe inexistente ou inativa'; END IF;
 IF length(btrim(COALESCE(p_shift,''))) NOT BETWEEN 2 AND 60 THEN
   RAISE EXCEPTION 'Informe turno entre 2 e 60 caracteres'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||p_day::text,0));
 IF EXISTS(SELECT 1 FROM public.sri_result_day_closures WHERE operational_day=p_day
    AND status IN ('closed','closed_with_pending'))
 THEN RAISE EXCEPTION 'Dia encerrado; reabertura necessária'; END IF;
 INSERT INTO public.shift_expectations(team_id,operational_day,shift_label,created_by)
 VALUES(p_team,p_day,btrim(p_shift),auth.uid()) ON CONFLICT DO NOTHING;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'RESULT_SHIFT_PLANNED','shift_expectation',p_day::text,
    jsonb_build_object('team_id',p_team,'shift',btrim(p_shift)));
END;
$function$
CREATE OR REPLACE FUNCTION public.admin_change_user_role(p_user_id uuid, p_new_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old_role text;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(
    SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='admin'
 ) THEN RAISE EXCEPTION 'Somente administradores podem alterar perfis'; END IF;
 IF p_new_role NOT IN ('operator','viewer','supervisor','manager','admin') THEN
    RAISE EXCEPTION 'Perfil inválido'; END IF;
 IF p_user_id=auth.uid() THEN RAISE EXCEPTION 'Não altere seu próprio perfil'; END IF;
 SELECT role INTO old_role FROM public.profiles WHERE id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF;
 IF old_role=p_new_role THEN RETURN; END IF;
 IF old_role='operator' AND p_new_role<>'operator' AND EXISTS(
    SELECT 1 FROM public.daily_operator_tasks WHERE operator_user_id=p_user_id AND active
 ) THEN RAISE EXCEPTION 'Redistribua as tarefas ativas antes de alterar o perfil Operador'; END IF;
 UPDATE public.profiles SET role=p_new_role WHERE id=p_user_id;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'USER_ROLE_CHANGED','profile',p_user_id::text,
   jsonb_build_object('old_role',old_role,'new_role',p_new_role));
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_lock_result_day_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||NEW.operational_day::text,0));
 IF EXISTS(SELECT 1 FROM public.sri_result_day_closures d
   WHERE d.operational_day=NEW.operational_day AND d.status IN ('closed','closed_with_pending'))
  OR EXISTS(SELECT 1 FROM public.sri_result_shift_closures c
   WHERE c.team_id=NEW.team_id AND c.operational_day=NEW.operational_day
     AND c.shift_label=NEW.shift_label AND c.status='closed')
 THEN RAISE EXCEPTION 'Turno ou dia já fechado; reabertura autorizada necessária'; END IF;
 RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_supervisor_can_view_user(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS(
   SELECT 1 FROM public.profiles me
   JOIN public.team_memberships own_team ON own_team.user_id=me.id
   JOIN public.team_memberships target_team ON target_team.team_id=own_team.team_id
   WHERE me.id=(SELECT auth.uid()) AND me.role='supervisor' AND target_team.user_id=p_user
