CREATE OR REPLACE FUNCTION public.sri_set_user_team(p_user uuid, p_team uuid, p_status text DEFAULT 'Ativo'::text, p_supervisor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; v_name text; v_sup_role text;
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN
   RAISE EXCEPTION 'Somente gestores e administradores podem configurar equipes';
 END IF;
 IF p_status NOT IN ('Ativo','Promovido','Férias','Afastamento','Desligado') THEN
   RAISE EXCEPTION 'Situação operacional inválida';
 END IF;
 SELECT role, full_name INTO v_role,v_name FROM public.profiles WHERE id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF;
 IF v_role NOT IN ('operator','supervisor') THEN
   RAISE EXCEPTION 'Esta configuração é destinada a operadores e supervisores';
 END IF;
 IF p_team IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.teams WHERE id=p_team AND active
 ) THEN RAISE EXCEPTION 'Selecione uma equipe ativa'; END IF;
 IF p_supervisor IS NOT NULL THEN
   IF v_role<>'operator' THEN RAISE EXCEPTION 'Supervisor responsável se aplica a Operadores'; END IF;
   SELECT role INTO v_sup_role FROM public.profiles WHERE id=p_supervisor;
   IF v_sup_role NOT IN ('supervisor','manager','admin') THEN
     RAISE EXCEPTION 'Supervisor responsável inválido'; END IF;
   IF p_team IS NULL OR (v_sup_role='supervisor' AND NOT EXISTS(
     SELECT 1 FROM public.team_memberships WHERE team_id=p_team AND user_id=p_supervisor
   )) THEN RAISE EXCEPTION 'O supervisor precisa estar na equipe selecionada'; END IF;
 END IF;
 -- Proteção de atribuições existentes em outras equipes.
 IF EXISTS (SELECT 1 FROM public.daily_operator_tasks t
   WHERE t.operator_user_id=p_user AND t.active AND private.sri_task_blocks_transfer(t.operational_day,t.team_id,t.shift_label)
    AND (p_team IS NULL OR t.team_id IS DISTINCT FROM p_team OR p_status NOT IN ('Ativo','Promovido')))
 THEN RAISE EXCEPTION 'Existem protocolos ativos; redistribua-os antes de mudar equipe ou indisponibilizar o operador';
 END IF;
 UPDATE public.profiles SET operational_status=p_status, supervisor_id=p_supervisor WHERE id=p_user;
 DELETE FROM public.team_memberships WHERE user_id=p_user AND (p_team IS NULL OR team_id<>p_team);
 IF p_team IS NOT NULL THEN
   INSERT INTO public.team_memberships(user_id,team_id) VALUES(p_user,p_team)
   ON CONFLICT DO NOTHING;
   IF v_role='operator' THEN
     -- Identificador técnico único. O nome visível permanece o do perfil.
     INSERT INTO public.operator_links(team_id,user_id,operator_name,linked_by)
     VALUES(p_team,p_user,'USER:'||p_user::text,auth.uid())
     ON CONFLICT (team_id,user_id) DO NOTHING;
   END IF;
 END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'USER_TEAM_CONFIGURED','profile',p_user::text,
   jsonb_build_object('team_id',p_team,'status',p_status,'supervisor_id',p_supervisor));
 RETURN jsonb_build_object('user_id',p_user,'team_id',p_team,'status',p_status);
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_result_closure_overview(p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_rows jsonb:='[]'::jsonb; v_rec record; v_snap record; v_c record; v_day_status text;
        v_pending int:=0; v_total int:=0; v_closed int:=0;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p
   WHERE p.id=auth.uid() AND p.role IN ('admin','manager','supervisor'))
 THEN RAISE EXCEPTION 'Apenas gestão/supervisão pode consultar fechamentos'; END IF;
 SELECT status INTO v_day_status FROM public.sri_result_day_closures WHERE operational_day=p_day;
 FOR v_rec IN
  SELECT e.team_id,e.shift_label,t.name AS team_name FROM
   (SELECT team_id,shift_label FROM public.shift_expectations WHERE operational_day=p_day
    UNION SELECT team_id,shift_label FROM public.daily_result_snapshots WHERE operational_day=p_day) e
   JOIN public.teams t ON t.id=e.team_id
  WHERE private.is_manager() OR private.is_supervisor_of(e.team_id)
  ORDER BY t.name,e.shift_label
 LOOP
  v_total:=v_total+1;
  SELECT s.id,s.protocol_count,s.indicators,s.warnings,s.created_at,d.revision
    INTO v_snap FROM public.daily_result_snapshots s
    LEFT JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
   WHERE s.team_id=v_rec.team_id AND s.operational_day=p_day AND s.shift_label=v_rec.shift_label
   ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
  SELECT c.id,c.status,c.closed_at,c.snapshot_id INTO v_c FROM public.sri_result_shift_closures c
   WHERE c.team_id=v_rec.team_id AND c.operational_day=p_day AND c.shift_label=v_rec.shift_label;
  IF COALESCE(v_c.status,'open')='closed' THEN v_closed:=v_closed+1;
  ELSE v_pending:=v_pending+1; END IF;
  v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
    'team_id',v_rec.team_id,'team_name',v_rec.team_name,'shift_label',v_rec.shift_label,
    'snapshot_id',v_snap.id,'distribution_revision',v_snap.revision,
    'protocol_count',v_snap.protocol_count,'indicators',COALESCE(v_snap.indicators,'{}'::jsonb),
    'warnings',COALESCE(v_snap.warnings,'{}'::jsonb),'status',COALESCE(v_c.status,'open'),
    'closed_at',v_c.closed_at,'closed_snapshot_id',v_c.snapshot_id,'closure_id',v_c.id));
 END LOOP;
 RETURN jsonb_build_object('day',p_day,'day_status',COALESCE(v_day_status,'open'),
    'total_shifts',v_total,'closed_shifts',v_closed,'pending_shifts',v_pending,'shifts',v_rows);
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_reopen_result_day(p_day date, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
 IF length(btrim(COALESCE(p_reason,'')))<10 THEN RAISE EXCEPTION 'Informe justificativa de pelo menos 10 caracteres'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||p_day::text,0));
 UPDATE public.sri_result_day_closures SET status='reopened',reopened_by=auth.uid(),
  reopened_at=now(),reopen_reason=btrim(p_reason) WHERE operational_day=p_day
  AND status IN ('closed','closed_with_pending') RETURNING id INTO v_id;
 IF v_id IS NULL THEN RAISE EXCEPTION 'Não existe fechamento ativo para reabrir'; END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'RESULT_DAY_REOPENED','sri_result_day_closure',v_id::text,jsonb_build_object('reason',p_reason));
 RETURN v_id;
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_close_result_day(p_day date, p_justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_expected int;v_pending int;v_snapshot_count int;v_id uuid;v_previous text;
        v_metrics jsonb;v_conf jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN
  RAISE EXCEPTION 'Somente Gestor/Administrador pode encerrar o dia'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||p_day::text,0));
 SELECT status INTO v_previous FROM public.sri_result_day_closures WHERE operational_day=p_day FOR UPDATE;
 IF v_previous IN ('closed','closed_with_pending') THEN RAISE EXCEPTION 'Dia já encerrado'; END IF;
 SELECT count(*) INTO v_snapshot_count FROM public.daily_result_snapshots WHERE operational_day=p_day;
 IF v_snapshot_count=0 THEN RAISE EXCEPTION 'Nenhuma apuração consolidada nesta data'; END IF;
 SELECT count(*),count(*) FILTER(WHERE c.status IS DISTINCT FROM 'closed') INTO v_expected,v_pending
 FROM (SELECT team_id,shift_label FROM public.shift_expectations WHERE operational_day=p_day
  UNION SELECT team_id,shift_label FROM public.daily_result_snapshots WHERE operational_day=p_day) e
 LEFT JOIN public.sri_result_shift_closures c ON c.team_id=e.team_id
  AND c.operational_day=p_day AND c.shift_label=e.shift_label;
 IF v_expected=0 THEN RAISE EXCEPTION 'Nenhum turno para conferência'; END IF;
 IF v_pending>0 AND length(btrim(COALESCE(p_justification,'')))<10 THEN
  RAISE EXCEPTION 'Fechamento com pendências exige justificativa de pelo menos 10 caracteres'; END IF;
 SELECT jsonb_build_object('protocol_count_sum',COALESCE(sum(s.protocol_count),0),
  'monitored_sum',COALESCE(sum(NULLIF(s.indicators->>'protocolos_monitorados','')::integer),0),
  'snapshots_count',count(*)) INTO v_metrics
 FROM (SELECT DISTINCT ON(team_id,shift_label) * FROM public.daily_result_snapshots WHERE operational_day=p_day
       ORDER BY team_id,shift_label,created_at DESC,id DESC) s;
 v_conf:=jsonb_build_object('day',p_day,'expected_shifts',v_expected,'closed_shifts',v_expected-v_pending,
   'pending_shifts',v_pending,'latest_snapshots',v_metrics,
   'notice','Somatório por turno; não equivale a protocolos únicos no dia');
 INSERT INTO public.sri_result_day_closures
 (operational_day,status,pending_shift_count,justification,conference,closed_by)
 VALUES(p_day,CASE WHEN v_pending>0 THEN 'closed_with_pending' ELSE 'closed' END,
        v_pending,NULLIF(btrim(COALESCE(p_justification,'')),''),v_conf,auth.uid())
 ON CONFLICT(operational_day) DO UPDATE SET
  status=EXCLUDED.status,pending_shift_count=EXCLUDED.pending_shift_count,
  justification=EXCLUDED.justification,conference=EXCLUDED.conference,
  closed_by=EXCLUDED.closed_by,closed_at=now(),reopened_at=NULL,reopened_by=NULL,reopen_reason=NULL
 WHERE public.sri_result_day_closures.status='reopened'
 RETURNING id INTO v_id;
 IF v_id IS NULL THEN RAISE EXCEPTION 'Dia já fechado ou requer reabertura autorizada'; END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'RESULT_DAY_CLOSED','sri_result_day_closure',v_id::text,
   v_conf||jsonb_build_object('justification',p_justification));
 RETURN jsonb_build_object('id',v_id,'status',CASE WHEN v_pending>0 THEN 'closed_with_pending' ELSE 'closed' END,
     'conference',v_conf);
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_close_result_shift(p_snapshot uuid, p_revision bigint, p_confirm_last_import boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_snap public.daily_result_snapshots%rowtype; v_dist bigint; v_newer uuid;
        v_existing public.sri_result_shift_closures%rowtype; v_id uuid;
        v_tasks integer; v_pending_tasks integer; v_expected_assignments integer; v_mismatched_tasks integer; v_conf jsonb;
BEGIN
 IF auth.uid() IS NULL OR p_confirm_last_import IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'Confirme explicitamente que esta é a última importação do turno'; END IF;
 SELECT * INTO v_snap FROM public.daily_result_snapshots WHERE id=p_snapshot;
 IF NOT FOUND THEN RAISE EXCEPTION 'Apuração não encontrada'; END IF;
 IF NOT(private.is_manager() OR private.is_supervisor_of(v_snap.team_id))
 THEN RAISE EXCEPTION 'Equipe não autorizada para fechamento'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_snap.operational_day::text,0));
 SELECT s.id INTO v_newer FROM public.daily_result_snapshots s WHERE s.team_id=v_snap.team_id
  AND s.operational_day=v_snap.operational_day AND s.shift_label=v_snap.shift_label
  ORDER BY s.created_at DESC,s.id DESC LIMIT 1;
 IF v_newer IS DISTINCT FROM p_snapshot THEN RAISE EXCEPTION 'Há apuração posterior: carregue a mais recente'; END IF;
 IF EXISTS(SELECT 1 FROM public.sri_result_day_closures WHERE operational_day=v_snap.operational_day
   AND status IN ('closed','closed_with_pending')) THEN RAISE EXCEPTION 'Dia geral encerrado'; END IF;
 SELECT d.revision INTO v_dist FROM public.daily_result_distributions d
  WHERE d.snapshot_id=p_snapshot FOR UPDATE;
 IF v_dist IS NULL OR v_dist<1 OR v_dist IS DISTINCT FROM p_revision
 THEN RAISE EXCEPTION 'Distribuição inexistente ou mudou: recarregue a apuração'; END IF;
 SELECT * INTO v_existing FROM public.sri_result_shift_closures
 WHERE team_id=v_snap.team_id AND operational_day=v_snap.operational_day AND shift_label=v_snap.shift_label FOR UPDATE;
 IF v_existing.status='closed' THEN RAISE EXCEPTION 'Este turno já foi fechado'; END IF;
 SELECT count(*),count(*) FILTER(WHERE work_status<>'completed_in_tool')
 INTO v_tasks,v_pending_tasks FROM public.daily_operator_tasks WHERE snapshot_id=p_snapshot AND active;
 -- Fechamento nao pode mascarar ausencia de publicacao ou revisao antiga.
 SELECT count(*) INTO v_expected_assignments FROM jsonb_object_keys(
   COALESCE((SELECT state->'assignments' FROM public.daily_result_distributions
             WHERE snapshot_id=p_snapshot),'{}'::jsonb));
 SELECT count(*) INTO v_mismatched_tasks FROM public.daily_operator_tasks
 WHERE snapshot_id=p_snapshot AND active AND distribution_revision<>v_dist;
 IF v_mismatched_tasks>0 THEN
   RAISE EXCEPTION 'Existem carteiras de uma revisão anterior: publique a distribuição atual antes de fechar';
 END IF;
 IF v_snap.protocol_count>0 AND v_tasks=0 THEN
   RAISE EXCEPTION 'Apuração com protocolos e nenhuma carteira publicada: conclua a distribuição antes de fechar';
 END IF;
 IF v_expected_assignments>v_tasks THEN
   RAISE EXCEPTION 'Há atribuições salvas sem publicação: confira os vínculos e publique todas as carteiras antes de fechar';
 END IF;
 v_conf:=jsonb_build_object('protocol_count',v_snap.protocol_count,'indicators',v_snap.indicators,
  'warnings',v_snap.warnings,'distribution_revision',v_dist,'published_tasks',v_tasks,
  'tasks_in_progress_or_pending',v_pending_tasks,'snapshot_id',p_snapshot,
  'notice','Fechamento operacional: não encerra protocolos no SIGO');
 IF v_existing.id IS NULL THEN
  INSERT INTO public.sri_result_shift_closures
  (team_id,operational_day,shift_label,snapshot_id,distribution_revision,conference,closed_by)
  VALUES(v_snap.team_id,v_snap.operational_day,v_snap.shift_label,p_snapshot,v_dist,v_conf,auth.uid())
  RETURNING id INTO v_id;
 ELSE
  UPDATE public.sri_result_shift_closures SET status='closed',snapshot_id=p_snapshot,
     distribution_revision=v_dist,conference=v_conf,closed_by=auth.uid(),closed_at=now(),
     reopened_at=NULL,reopened_by=NULL,reopen_reason=NULL WHERE id=v_existing.id RETURNING id INTO v_id;
 END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'RESULT_SHIFT_CLOSED','sri_result_shift_closure',v_id::text,v_conf);
 RETURN jsonb_build_object('id',v_id,'status','closed','conference',v_conf);
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_reopen_result_shift(p_closure uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_day date;
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN RAISE EXCEPTION 'Acesso negado'; END IF;
 IF length(btrim(COALESCE(p_reason,'')))<10 THEN RAISE EXCEPTION 'Informe justificativa de pelo menos 10 caracteres'; END IF;
 SELECT operational_day INTO v_day FROM public.sri_result_shift_closures WHERE id=p_closure;
 IF v_day IS NULL THEN RAISE EXCEPTION 'Fechamento inexistente'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_day::text,0));
 IF EXISTS(SELECT 1 FROM public.sri_result_day_closures WHERE operational_day=v_day
   AND status IN ('closed','closed_with_pending')) THEN
  RAISE EXCEPTION 'Reabra o fechamento geral antes de reabrir o turno'; END IF;
 UPDATE public.sri_result_shift_closures SET status='reopened',reopened_by=auth.uid(),
   reopened_at=now(),reopen_reason=btrim(p_reason) WHERE id=p_closure AND status='closed' RETURNING id INTO v_id;
 IF v_id IS NULL THEN RAISE EXCEPTION 'Turno não está encerrado'; END IF;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
 VALUES(auth.uid(),'RESULT_SHIFT_REOPENED','sri_result_shift_closure',v_id::text,jsonb_build_object('reason',p_reason));
 RETURN v_id;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_rename_user_impl(p_user uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_old text; v_role text; v_actor text;
BEGIN
 SELECT role INTO v_actor FROM public.profiles WHERE id=auth.uid();
 IF auth.uid() IS NULL OR v_actor IS NULL OR v_actor NOT IN ('admin','manager') THEN RAISE EXCEPTION 'Ação exclusiva da gestão'; END IF;
 IF length(btrim(coalesce(p_name,'')))<2 OR length(btrim(p_name))>120 THEN RAISE EXCEPTION 'Informe um nome válido'; END IF;
 SELECT full_name,role INTO v_old,v_role FROM public.profiles WHERE id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF;
 IF v_actor='manager' AND v_role NOT IN ('operator','supervisor') THEN RAISE EXCEPTION 'Ação exclusiva do administrador'; END IF;
 UPDATE public.profiles SET full_name=btrim(p_name) WHERE id=p_user;
 INSERT INTO public.audit_events(user_id,action,object_type,object_id,details) VALUES(auth.uid(),'USER_NAME_CHANGED','profile',p_user::text,jsonb_build_object('before',v_old,'after',btrim(p_name)));
END; $function$
