CREATE OR REPLACE FUNCTION public.sri_admin_history(p_kind text, p_id uuid)
 RETURNS TABLE(occurred_at timestamp with time zone, actor_name text, action text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ SELECT * FROM private.sri_admin_history_impl(p_kind,p_id) $function$
CREATE OR REPLACE FUNCTION private.sri_admin_history_impl(p_kind text, p_id uuid)
 RETURNS TABLE(occurred_at timestamp with time zone, actor_name text, action text, details jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT private.is_manager() THEN RAISE EXCEPTION 'Ação exclusiva da gestão'; END IF;
 IF p_kind NOT IN ('teams','operations','profile') OR p_id IS NULL THEN RAISE EXCEPTION 'Cadastro inválido'; END IF;
 RETURN QUERY SELECT a.occurred_at,p.full_name,a.action,a.details FROM public.audit_events a
 LEFT JOIN public.profiles p ON p.id=a.user_id
 WHERE a.object_id=p_id::text AND (a.object_type=p_kind OR (p_kind='teams' AND a.object_type='team'))
 AND a.action IN ('CATALOG_CREATE','CATALOG_EDIT','CATALOG_DISABLE','CATALOG_ENABLE','CATALOG_DELETE','TEAM_READY','USER_NAME_CHANGED','USER_TEAM_CONFIGURED','USER_ROLE_CHANGED')
 ORDER BY a.occurred_at DESC LIMIT 100;
END; $function$
CREATE OR REPLACE FUNCTION public.sri_distribution_operator_candidates(p_team uuid)
 RETURNS TABLE(user_id uuid, full_name text, operational_status text, team_id uuid, supervisor_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF (SELECT auth.uid()) IS NULL OR NOT (private.is_manager() OR private.is_supervisor_of(p_team)) THEN
    RAISE EXCEPTION 'Somente gestão ou supervisão da equipe pode consultar candidatos';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.teams t WHERE t.id=p_team AND t.active) THEN
    RAISE EXCEPTION 'Selecione uma equipe ativa';
  END IF;

  RETURN QUERY
  SELECT p.id, COALESCE(NULLIF(btrim(p.full_name),''),'Operador sem nome'),
         p.operational_status, tm.team_id,
         COALESCE(NULLIF(btrim(s.full_name),''),t.name,'Sem supervisor')
  FROM public.profiles p
  LEFT JOIN public.team_memberships tm ON tm.user_id=p.id AND tm.team_id=p_team
  LEFT JOIN public.teams t ON t.id=tm.team_id
  LEFT JOIN public.profiles s ON s.id=p.supervisor_id
  WHERE p.role='operator'
    AND p.operational_status IN ('Ativo','Promovido')
    -- Evitar exposição ou transferência de pessoas vinculadas a outra equipe.
    AND NOT EXISTS (
      SELECT 1 FROM public.team_memberships other
       WHERE other.user_id=p.id AND other.team_id<>p_team
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.daily_operator_tasks linked
       WHERE linked.operator_user_id=p.id AND linked.team_id IS DISTINCT FROM p_team AND linked.active AND private.sri_task_blocks_transfer(linked.operational_day,linked.team_id,linked.shift_label)
    )
  ORDER BY p.full_name, p.id;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_carry_task_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old_task public.daily_operator_tasks%rowtype;
BEGIN
 SELECT t.* INTO old_task FROM public.daily_operator_tasks t
 JOIN public.daily_result_snapshots s ON s.id=t.snapshot_id
 JOIN public.daily_result_snapshots n ON n.id=NEW.snapshot_id
 WHERE t.operational_day=NEW.operational_day AND t.shift_label=NEW.shift_label
 AND t.protocol_number=NEW.protocol_number AND t.snapshot_id<>NEW.snapshot_id
 AND (s.team_id IS NOT DISTINCT FROM n.team_id) AND t.active
 ORDER BY t.updated_at DESC,t.id DESC LIMIT 1;
 IF FOUND THEN NEW.treatment_status:=old_task.treatment_status;NEW.work_status:=old_task.work_status; END IF;
 RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_close_due_days(p_clock timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_local timestamp;
  v_limit date;
  v_day date;
  v_snapshot record;
  v_tasks integer;
  v_mismatch integer;
  v_assignments integer;
  v_expected integer;
  v_pending integer;
  v_conf jsonb;
  v_metrics jsonb;
  v_closure uuid;
  v_closed_shifts integer := 0;
  v_closed_days integer := 0;
  v_pending_days integer := 0;
BEGIN
  v_local := p_clock AT TIME ZONE 'America/Sao_Paulo';
  v_limit := v_local::date - CASE WHEN v_local::time < time '20:00:00' THEN 1 ELSE 0 END;

  -- Reconstitui fechamentos pendentes mesmo se o job falhou em uma rodada.
  FOR v_day IN
    SELECT DISTINCT s.operational_day
    FROM public.daily_result_snapshots s
    WHERE s.team_id IS NOT NULL AND s.operational_day <= v_limit
      AND NOT EXISTS (
        SELECT 1 FROM public.sri_result_day_closures c
        WHERE c.operational_day=s.operational_day
      )
    ORDER BY s.operational_day
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('sri-result-day:'||v_day::text,0));
    -- Nunca refazer fechamento/reabertura deliberada pela gestao.
    IF EXISTS(SELECT 1 FROM public.sri_result_day_closures d WHERE d.operational_day=v_day) THEN
      CONTINUE;
    END IF;

    FOR v_snapshot IN
      SELECT DISTINCT ON (s.team_id,s.shift_label)
        s.id,s.team_id,s.operational_day,s.shift_label,s.protocol_count,s.indicators,s.warnings,
        d.revision,d.state
      FROM public.daily_result_snapshots s
      LEFT JOIN public.daily_result_distributions d ON d.snapshot_id=s.id
      WHERE s.team_id IS NOT NULL AND s.operational_day=v_day
      ORDER BY s.team_id,s.shift_label,s.created_at DESC,s.id DESC
    LOOP
      -- Nao ocultar uma reabertura manual ou converter uma apuracao incompleta em "fechada".
      IF EXISTS(
        SELECT 1 FROM public.sri_result_shift_closures c
        WHERE c.team_id=v_snapshot.team_id AND c.operational_day=v_day
          AND c.shift_label=v_snapshot.shift_label
      ) THEN CONTINUE; END IF;
      IF v_snapshot.revision IS NULL OR v_snapshot.revision < 1 THEN CONTINUE; END IF;
      IF jsonb_typeof(v_snapshot.state->'assignments') IS DISTINCT FROM 'object' THEN CONTINUE; END IF;

      SELECT count(*),
             count(*) FILTER (WHERE distribution_revision IS DISTINCT FROM v_snapshot.revision)
      INTO v_tasks,v_mismatch
      FROM public.daily_operator_tasks t
      WHERE t.snapshot_id=v_snapshot.id AND t.active;
      SELECT count(*) INTO v_assignments
      FROM jsonb_object_keys(COALESCE(v_snapshot.state->'assignments','{}'::jsonb));
      IF v_mismatch>0 OR v_assignments>v_tasks OR
        (v_snapshot.protocol_count>0 AND v_tasks=0) THEN CONTINUE; END IF;

      v_conf:=jsonb_build_object(
        'automatic',true,'cutoff_local','20:00','time_zone','America/Sao_Paulo',
        'protocol_count',v_snapshot.protocol_count,'indicators',v_snapshot.indicators,
        'warnings',v_snapshot.warnings,'distribution_revision',v_snapshot.revision,
        'published_tasks',v_tasks,'snapshot_id',v_snapshot.id,
        'notice','Fechamento administrativo automatico: nao encerra protocolos no SIGO');
      INSERT INTO public.sri_result_shift_closures
        (team_id,operational_day,shift_label,snapshot_id,distribution_revision,conference,closed_by)
      VALUES(v_snapshot.team_id,v_day,v_snapshot.shift_label,v_snapshot.id,
             v_snapshot.revision,v_conf,NULL)
      ON CONFLICT (team_id,operational_day,shift_label) DO NOTHING
      RETURNING id INTO v_closure;
      IF v_closure IS NOT NULL THEN
        v_closed_shifts:=v_closed_shifts+1;
        INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
        VALUES(NULL,'RESULT_SHIFT_AUTO_CLOSED','sri_result_shift_closure',v_closure::text,v_conf);
      END IF;
      v_closure:=NULL;
    END LOOP;

    SELECT count(*), count(*) FILTER (WHERE c.status IS DISTINCT FROM 'closed')
    INTO v_expected,v_pending
    FROM (
      SELECT team_id,shift_label FROM public.shift_expectations WHERE operational_day=v_day
      UNION
      SELECT team_id,shift_label FROM public.daily_result_snapshots WHERE operational_day=v_day AND team_id IS NOT NULL
    ) x
    LEFT JOIN public.sri_result_shift_closures c
      ON c.team_id=x.team_id AND c.operational_day=v_day AND c.shift_label=x.shift_label;
    IF v_expected=0 THEN CONTINUE; END IF;
    SELECT jsonb_build_object(
        'protocol_count_sum',COALESCE(sum(s.protocol_count),0),
        'monitored_sum',COALESCE(sum(NULLIF(s.indicators->>'protocolos_monitorados','')::integer),0),
        'snapshots_count',count(*))
    INTO v_metrics
    FROM (
      SELECT DISTINCT ON (team_id,shift_label) *
      FROM public.daily_result_snapshots
      WHERE operational_day=v_day AND team_id IS NOT NULL
      ORDER BY team_id,shift_label,created_at DESC,id DESC
    ) s;
    v_conf:=jsonb_build_object(
      'automatic',true,'cutoff_local','20:00','time_zone','America/Sao_Paulo',
      'day',v_day,'expected_shifts',v_expected,'closed_shifts',v_expected-v_pending,
      'pending_shifts',v_pending,'latest_snapshots',v_metrics,
      'notice','Somatorio por turno; nao equivale a protocolos unicos no dia');
    INSERT INTO public.sri_result_day_closures
      (operational_day,status,pending_shift_count,justification,conference,closed_by)
    VALUES(v_day,
           CASE WHEN v_pending>0 THEN 'closed_with_pending' ELSE 'closed' END,
           v_pending,
           CASE WHEN v_pending>0
             THEN 'Fechamento automatico as 20h: turnos incompletos permanecem sinalizados para a gestao'
             ELSE NULL END,
           v_conf,NULL)
    ON CONFLICT(operational_day) DO NOTHING
    RETURNING id INTO v_closure;
    IF v_closure IS NOT NULL THEN
      v_closed_days:=v_closed_days+1;
      IF v_pending>0 THEN v_pending_days:=v_pending_days+1; END IF;
      INSERT INTO public.audit_events(user_id,action,object_type,object_id,details)
      VALUES(NULL,'RESULT_DAY_AUTO_CLOSED','sri_result_day_closure',v_closure::text,v_conf);
    END IF;
    v_closure:=NULL;
  END LOOP;
  RETURN jsonb_build_object('automatic',true,'closed_days',v_closed_days,
           'closed_shifts',v_closed_shifts,'days_with_pending',v_pending_days,
           'evaluated_until',v_limit,'time_zone','America/Sao_Paulo');
END;
$function$
CREATE OR REPLACE FUNCTION public.sri_set_status_compatibility(p_source text, p_treatment text, p_compatible boolean, p_reason text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$ SELECT private.sri_set_status_compatibility(p_source,p_treatment,p_compatible,p_reason); $function$
CREATE OR REPLACE FUNCTION private.sri_detect_reconciliation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prior public.daily_operator_tasks%rowtype;
BEGIN
 IF NEW.treatment_status IS NULL OR NEW.treatment_status IN ('','SEM STATUS') OR NEW.source_status IS NULL OR NEW.source_status !~ '^[0-9]+$' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.source_status IS NOT DISTINCT FROM NEW.source_status THEN RETURN NEW; END IF;
  prior:=OLD;
 ELSE
  SELECT t.* INTO prior FROM public.daily_operator_tasks t
  JOIN public.daily_result_snapshots s ON s.id=t.snapshot_id
  JOIN public.daily_result_snapshots n ON n.id=NEW.snapshot_id
  WHERE t.protocol_number=NEW.protocol_number AND t.operational_day=NEW.operational_day
  AND s.team_id IS NOT DISTINCT FROM n.team_id AND t.snapshot_id<>NEW.snapshot_id
  ORDER BY s.created_at DESC,t.updated_at DESC,t.id DESC LIMIT 1;
 END IF;
 IF prior.source_status IS NULL OR prior.source_status !~ '^[0-9]+$' OR prior.source_status=NEW.source_status THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM private.sri_status_compatibility m WHERE m.source_status=NEW.source_status AND m.treatment_status=NEW.treatment_status AND m.compatible) THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM private.sri_status_reconciliation r WHERE r.operational_day=NEW.operational_day
 AND r.protocol_number=NEW.protocol_number AND r.team_id IS NOT DISTINCT FROM NEW.team_id
 AND r.snapshot_id=NEW.snapshot_id AND r.previous_source=prior.source_status AND r.current_source=NEW.source_status AND r.manual_status=NEW.treatment_status) THEN RETURN NEW; END IF;
 INSERT INTO private.sri_status_reconciliation(task_id,snapshot_id,protocol_number,operational_day,team_id,operator_id,base_name,area_name,previous_source,current_source,manual_status)
 VALUES(NEW.id,NEW.snapshot_id,NEW.protocol_number,NEW.operational_day,NEW.team_id,NEW.operator_user_id,NEW.base_name,NEW.area_name,prior.source_status,NEW.source_status,NEW.treatment_status)
 ON CONFLICT DO NOTHING;
 RETURN NEW;
END;
$function$
CREATE OR REPLACE FUNCTION private.sri_list_reconciliation(p_day date)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT to_jsonb(r)||jsonb_build_object('operator_name',p.full_name,'team_name',t.name,'reviewer_name',u.full_name)
 FROM private.sri_status_reconciliation r LEFT JOIN public.profiles p ON p.id=r.operator_id
 LEFT JOIN public.teams t ON t.id=r.team_id LEFT JOIN public.profiles u ON u.id=r.decided_by
 WHERE auth.uid() IS NOT NULL AND r.operational_day=p_day
 AND (private.is_manager() OR (r.team_id IS NOT NULL AND private.is_supervisor_of(r.team_id)))
 ORDER BY r.observed_at DESC,r.id DESC LIMIT 2000
$function$
